					<div class="section-heading"><div><h2>Payment records</h2><p>Record receipts and update verification status. Paid totals update the linked order.</p></div></div>
					<div class="panel"><h3>Record a payment</h3><?php if ($orderChoices): ?><form method="post" action="admindashboard.php?tab=payments">
						<input type="hidden" name="csrf_token" value="<?= e($_SESSION['admin_csrf']) ?>"><input type="hidden" name="tab" value="payments"><input type="hidden" name="action" value="record_payment">
						<div class="fields four"><div class="field"><label for="payment-order">Order</label><select id="payment-order" name="order_id" required><?php foreach ($orderChoices as $order): ?><option value="<?= (int) $order['id'] ?>"><?= e($order['order_number']) ?> · $<?= number_format((float) $order['total_amount'], 2) ?></option><?php endforeach; ?></select></div>
						<div class="field"><label for="payment-method">Method</label><select id="payment-method" name="payment_method"><option value="COD">Cash on delivery</option><option value="BANK_TRANSFER">Bank transfer</option><option value="ONLINE_CARD">Online card</option></select></div>
						<div class="field"><label for="payment-amount">Amount</label><input id="payment-amount" name="amount_paid" type="number" min="0.01" step="0.01" required></div><div class="field"><label for="payment-new-status">Verification status</label><select id="payment-new-status" name="payment_status"><option>PENDING</option><option>PAID</option><option>FAILED</option><option>REFUNDED</option></select></div>
						<div class="field wide"><label for="payment-reference">Transaction reference</label><input id="payment-reference" name="transaction_reference" maxlength="100"></div></div><div class="form-actions"><button class="primary" type="submit">Save payment</button></div>
					</form><?php else: ?><p class="hint">Payments can be recorded after an order exists.</p><?php endif; ?></div>
					<div class="table-wrap"><table><thead><tr><th>Recorded</th><th>Order</th><th>Method</th><th>Amount</th><th>Reference</th><th>Recorded by</th><th>Status / update</th></tr></thead><tbody>
					<?php foreach ($payments as $row): ?><tr><td><?= e($row['created_at']) ?></td><td><strong><?= e($row['order_number']) ?></strong></td><td><?= e(str_replace('_', ' ', $row['payment_method'])) ?></td><td>$<?= number_format((float) $row['amount_paid'], 2) ?></td><td><?= e($row['transaction_reference']) ?></td><td><?= e($row['recorded_by'] ?: '—') ?></td><td><form class="pay-status" method="post" action="admindashboard.php?tab=payments">
							<input type="hidden" name="csrf_token" value="<?= e($_SESSION['admin_csrf']) ?>"><input type="hidden" name="tab" value="payments"><input type="hidden" name="action" value="update_payment"><input type="hidden" name="payment_id" value="<?= (int) $row['id'] ?>">
							<select name="payment_status"><?php foreach (['PENDING','PAID','FAILED','REFUNDED'] as $paymentStatusOption): ?><option <?= $row['payment_status'] === $paymentStatusOption ? 'selected' : '' ?>><?= e($paymentStatusOption) ?></option><?php endforeach; ?></select><button type="submit">Save</button>
						</form></td></tr><?php endforeach; ?>
					<?php if (!$payments): ?><tr><td colspan="7" class="empty">No payments recorded.</td></tr><?php endif; ?>
					</tbody></table></div>